def work_on_strings(a, b):
    def swap_case(char):
        if char.islower():
            return char.upper()
        elif char.isupper():
            return char.lower()
        else:
            return char

    # Process string b based on occurrences in a
    b_list = list(b)
    for char_a in a:
        for i in range(len(b_list)):
            if b_list[i].lower() == char_a.lower():
                b_list[i] = swap_case(b_list[i])

    # Process string a based on occurrences in modified b
    a_list = list(a)
    for char_b in b_list:
        for i in range(len(a_list)):
            if a_list[i].lower() == char_b.lower():
                a_list[i] = swap_case(a_list[i])

    return "".join(a_list) + "".join(b_list)
